<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import PageHeading from '../components/PageHeading.vue';import {useData,useUI} from '../store';import DeviceMerge from '../components/DeviceMerge.vue';import ManualOta from '../components/ManualOta.vue';import type {Machine} from '../types';import {online,accountName,date,remaining} from '../domain';
const data=useData(),ui=useUI(),route=useRoute(),router=useRouter(),selectedId=ref<number|null>(null),composing=ref(false),draft=ref(String(route.query.q||''));
// 只保存设备ID，详情随最新快照更新，不持有已过期的行对象。
const mergeSource=ref<Machine|null>(null);
const selected=computed(()=>data.snapshot?.machines.find(machine=>machine.machine_id===selectedId.value)||null);
watch(()=>data.snapshot,()=>{if(selectedId.value!==null&&!selected.value)selectedId.value=null;});
const filter=computed({get:()=>String(route.query.status||'all'),set:value=>{void router.replace({query:{...route.query,status:value,page:'1'}});}});
const page=computed({get:()=>Math.max(1,Number(route.query.page)||1),set:value=>{void router.replace({query:{...route.query,page:String(value)}});}});
const list=computed(()=>[...(data.snapshot?.machines||[])].filter(m=>(filter.value==='all'||(filter.value==='online')===online(m,data.now))&&`${m.label} ${m.hostname||''} ${accountName(m)} ${m.owner||''}`.toLocaleLowerCase('zh-CN').includes(String(route.query.q||'').toLocaleLowerCase('zh-CN'))).sort((a,b)=>Number(online(b,data.now))-Number(online(a,data.now))||a.label.localeCompare(b.label,'zh-CN')));
watch(()=>route.query.q,value=>draft.value=String(value||''));watch(()=>list.value.length,n=>{const max=Math.max(1,Math.ceil(n/10));if(page.value>max)page.value=max;});
/** 功能：管理员选择离线旧设备打开合并预览；参数：设备；返回值：无。 */
function openMerge(machine:Machine){if(!ui.authorized){ui.authOpen=true;return;}mergeSource.value=machine;}
/** 功能：提交本地搜索，避免输入法组合期间更新路由；参数：value；返回值：无。 */
function search(value:string){if(!composing.value)void router.replace({query:{...route.query,q:value||undefined,page:'1'}});}
</script><template><PageHeading title="设备监控" note="账号归属来自已核验读数，设备在线按成功上报时间、实际周期及2分钟宽限判断。" eyebrow="DEVICE OPERATIONS"><RouterLink to="/access"><el-button type="primary">接入新设备</el-button></RouterLink></PageHeading><div class="toolbar"><el-radio-group v-model="filter"><el-radio-button value="all">全部设备</el-radio-button><el-radio-button value="online">在线</el-radio-button><el-radio-button value="offline">离线</el-radio-button></el-radio-group><el-input v-model="draft" clearable placeholder="搜索设备、账号、负责人" aria-label="搜索设备" style="width:290px" @input="search" @clear="search('')" @compositionstart="composing=true" @compositionend="composing=false;search(draft)"/></div><section class="table-panel"><el-table :data="list.slice((page-1)*10,page*10)" empty-text="没有符合筛选条件的设备" row-key="machine_id"><el-table-column label="设备 / 主机名" min-width="180"><template #default="{row}"><strong>{{row.label}}</strong><el-tag v-if="online(row,data.now) &amp;&amp; row.online_since != null &amp;&amp; data.now &gt;= row.online_since &amp;&amp; data.now-row.online_since &lt; 300" size="small" type="success">刚上线</el-tag><small class="cell-sub">本次上线：{{row.online_since == null ? '未知' : date(row.online_since)}}</small><small class="cell-sub">{{row.hostname||'主机名未知'}}</small></template></el-table-column><el-table-column label="最近核验账号" min-width="200"><template #default="{row}">{{accountName(row)}}<small class="cell-sub">{{row.source==='app_server'?'app-server核验来源':'身份未由app-server核验'}}</small></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><span class="status-pill" :class="{offline:!online(row,data.now)}">{{online(row,data.now)?'在线':'离线'}}</span></template></el-table-column><el-table-column label="最近成功上报" min-width="170"><template #default="{row}">{{date(row.last_ok_at)}}</template></el-table-column><el-table-column label="最近来源 IP" min-width="150"><template #default="{row}">{{row.last_ip||'未知'}}</template></el-table-column><el-table-column label="实际周期" width="120"><template #default="{row}">{{row.reporting.applied_interval_minutes}} 分钟<small class="cell-sub">{{row.reporting.pending?'待应用':'已确认'}}</small></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="selectedId=row.machine_id">查看详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="list.length" layout="total,prev,pager,next" class="pager"/></section>
<ManualOta/><el-drawer :model-value="Boolean(selected)" title="设备详情" size="min(480px,100vw)" destroy-on-close @close="selectedId=null"><template v-if="selected"><h2>{{selected.label}}</h2><p class="small-label">{{selected.hostname}}</p><el-descriptions :column="1" border><el-descriptions-item label="client_id">{{selected.client_id}}</el-descriptions-item><el-descriptions-item :label="selected.source==='app_server'?'核验账号':'历史观察账号'">{{accountName(selected)}}</el-descriptions-item><el-descriptions-item label="最近成功上报">{{date(selected.last_ok_at)}}</el-descriptions-item><el-descriptions-item label="最近来源 IP">{{selected.last_ip||'未知'}}</el-descriptions-item><el-descriptions-item label="Codex版本">{{selected.cli_version||'未知'}}</el-descriptions-item><el-descriptions-item label="采集器版本">{{selected.collector_version||'未知'}}</el-descriptions-item><el-descriptions-item label="构建编号">{{selected.collector_build||'未知'}}</el-descriptions-item><el-descriptions-item label="程序 SHA-256"><span style="overflow-wrap:anywhere">{{selected.collector_sha256||'未知'}}</span></el-descriptions-item><el-descriptions-item label="实际上报周期">{{selected.reporting.applied_interval_minutes}} 分钟</el-descriptions-item><el-descriptions-item label="离线阈值">{{selected.online_window_sec/60}} 分钟未成功上报</el-descriptions-item><el-descriptions-item label="期望周期">{{selected.reporting.desired_interval_minutes}} 分钟</el-descriptions-item><el-descriptions-item label="应用状态">{{selected.reporting.apply_error?'应用失败':selected.reporting.pending?'等待客户端确认':'已确认'}}</el-descriptions-item></el-descriptions><el-alert title="未提供采集器性能接口，不展示推测的内存、CPU或阶段耗时。" type="info" :closable="false" class="global-alert"/><div class="drawer-actions"><el-button @click="ui.open({kind:'label',target:{...selected}})">设备改名</el-button><el-button @click="ui.open({kind:'period',target:{...selected}})">设置周期</el-button></div><el-button type="warning" :disabled="online(selected,data.now)" @click="openMerge(selected)">合并旧设备</el-button><p class="small-label">合并入口仅允许离线旧记录；选择要保留的目标设备，目标身份不变。</p><p>主窗口剩余：{{remaining(selected)===null?'未知':remaining(selected)+'%'}}</p></template></el-drawer><DeviceMerge :source="mergeSource" @close="mergeSource=null"/></template>
